import { useState, useId, type FormEvent } from 'react';
import { usePasswordReset } from '../../hooks/usePasswordReset';
import { useInstantLink } from '../../hooks/useInstantLink';
import { ErrorMessage } from '../shared/ErrorMessage';
import { LoadingSpinner } from '../shared/LoadingSpinner';

export interface ForgotPasswordFormProps {
  /** Which action to perform: password reset email or instant sign-in link */
  mode?: 'reset' | 'instantLink';
  onSuccess?: () => void;
  onCancel?: () => void;
  className?: string;
}

const COPY = {
  reset: {
    subtitle: "Enter your email address and we'll send you a link to reset your password.",
    button: 'Send reset link',
    successMessage: (email: string) => (
      <>
        If an account exists for <strong>{email}</strong>, you will receive a password reset link
        shortly.
      </>
    ),
  },
  instantLink: {
    subtitle:
      "Enter your email and we'll send you a sign-in link. You can change your password in your account settings once signed in.",
    button: 'Send sign-in link',
    successMessage: (email: string) => (
      <>
        We sent a sign-in link to <strong>{email}</strong>. Click the link to sign in.
      </>
    ),
  },
} as const;

/**
 * Form for requesting a password reset or instant sign-in link.
 *
 * @param mode - `'reset'` sends a password reset email; `'instantLink'` sends a passwordless sign-in link.
 */
export function ForgotPasswordForm({
  mode = 'reset',
  onSuccess,
  onCancel,
  className = '',
}: ForgotPasswordFormProps) {
  const [email, setEmail] = useState('');
  const passwordReset = usePasswordReset();
  const instantLink = useInstantLink();
  const emailId = useId();

  const hook = mode === 'instantLink'
    ? { submit: instantLink.sendInstantLink, isLoading: instantLink.isLoading, isSuccess: instantLink.isSuccess, error: instantLink.error, clearError: instantLink.clearError }
    : { submit: passwordReset.forgotPassword, isLoading: passwordReset.isLoading, isSuccess: passwordReset.isSuccess, error: passwordReset.error, clearError: passwordReset.clearError };

  const copy = COPY[mode];

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      await hook.submit(email);
      onSuccess?.();
    } catch {
      // Error is already set in the hook
    }
  };

  if (hook.isSuccess) {
    return (
      <div className={`cedros-forgot-password-success ${className}`}>
        <svg
          className="cedros-success-icon"
          width="48"
          height="48"
          viewBox="0 0 48 48"
          fill="none"
          aria-hidden="true"
        >
          <circle cx="24" cy="24" r="22" stroke="currentColor" strokeWidth="2" />
          <path
            d="M14 24l7 7 13-13"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
        <h3 className="cedros-success-title">Check your email</h3>
        <p className="cedros-success-message">{copy.successMessage(email)}</p>
        {onCancel && (
          <button
            type="button"
            className="cedros-button cedros-button-md cedros-button-outline"
            onClick={onCancel}
          >
            Back to login
          </button>
        )}
      </div>
    );
  }

  return (
    <form className={`cedros-forgot-password-form ${className}`} onSubmit={handleSubmit}>
      <div className="cedros-form-header">
        <h3 className="cedros-form-title">Forgot password?</h3>
        <p className="cedros-form-subtitle">{copy.subtitle}</p>
      </div>

      <ErrorMessage error={hook.error} onDismiss={hook.clearError} />

      <div className="cedros-form-field">
        <label htmlFor={emailId} className="cedros-label">
          Email address
        </label>
        <input
          id={emailId}
          type="email"
          className="cedros-input"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="you@example.com"
          required
          autoComplete="email"
          disabled={hook.isLoading}
        />
      </div>

      <div className="cedros-form-actions">
        <button
          type="submit"
          className="cedros-button cedros-button-md cedros-button-primary cedros-button-full"
          disabled={hook.isLoading || !email}
        >
          {hook.isLoading ? (
            <>
              <LoadingSpinner size="sm" />
              Sending...
            </>
          ) : (
            copy.button
          )}
        </button>

        {onCancel && (
          <button
            type="button"
            className="cedros-button cedros-button-md cedros-button-ghost cedros-button-full"
            onClick={onCancel}
            disabled={hook.isLoading}
          >
            Back to login
          </button>
        )}
      </div>
    </form>
  );
}
