import { Fragment, useState, useCallback, useEffect, type ReactNode } from 'react';
import { useCedrosLogin } from '../context/useCedrosLogin';
import { EmailLoginForm } from './email/EmailLoginForm';
import { EmailRegisterForm } from './email/EmailRegisterForm';
import { ForgotPasswordForm } from './email/ForgotPasswordForm';
import { GoogleLoginButton } from './google/GoogleLoginButton';
import { AppleLoginButton } from './apple/AppleLoginButton';
import { PasskeyLoginButton } from './webauthn/PasskeyLoginButton';
import { ErrorMessage } from './shared/ErrorMessage';
import { isAppleDevice } from '../utils/deviceDetection';
import { useServerFeatures } from '../hooks/useServerFeatures';

type TabValue = 'login' | 'register';
type ViewState = 'form' | 'forgotPassword';

const TABS: TabValue[] = ['login', 'register'];

export interface LoginFormProps {
  onSuccess?: () => void;
  className?: string;
  defaultTab?: 'login' | 'register';
}

export interface SolanaButtonRenderProps {
  onSuccess?: () => void;
  onError?: (error: Error) => void;
  accessCode?: string;
}

interface LoginFormBaseProps extends LoginFormProps {
  getHasWallets?: () => boolean;
  renderSolanaButton?: (props: SolanaButtonRenderProps) => ReactNode;
}

export function LoginFormBase({
  onSuccess,
  className = '',
  defaultTab = 'login',
  getHasWallets,
  renderSolanaButton,
}: LoginFormBaseProps) {
  const { config, socialButtonOrder, isFeatureEnabled } = useCedrosLogin();
  const { features: serverFeatures } = useServerFeatures();
  const [activeTab, setActiveTab] = useState<TabValue>(defaultTab);
  const [viewState, setViewState] = useState<ViewState>('form');
  const [hasWallets, setHasWallets] = useState(() => (getHasWallets ? getHasWallets() : false));
  const [isApple] = useState(() => isAppleDevice());
  const [accessCode, setAccessCode] = useState('');
  const [socialError, setSocialError] = useState<string | null>(null);

  const signupAccessCodeRequired = serverFeatures?.signupAccessCodeRequired ?? false;

  const handleSocialError = useCallback((err: Error) => {
    setSocialError(err.message);
  }, []);

  useEffect(() => {
    if (!getHasWallets) {
      return;
    }

    const updateWallets = () => setHasWallets(getHasWallets());
    updateWallets();
    window.addEventListener('load', updateWallets);
    window.addEventListener('focus', updateWallets);

    return () => {
      window.removeEventListener('load', updateWallets);
      window.removeEventListener('focus', updateWallets);
    };
  }, [getHasWallets]);

  const forgotPasswordMode = config.forms?.forgotPassword?.mode
    ?? (isFeatureEnabled('instantLink') ? 'instantLink' : 'reset');

  const handleTabKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLButtonElement>) => {
      const currentIndex = TABS.indexOf(activeTab);
      let newIndex = currentIndex;

      switch (e.key) {
        case 'ArrowLeft':
        case 'ArrowUp':
          newIndex = currentIndex === 0 ? TABS.length - 1 : currentIndex - 1;
          break;
        case 'ArrowRight':
        case 'ArrowDown':
          newIndex = currentIndex === TABS.length - 1 ? 0 : currentIndex + 1;
          break;
        case 'Home':
          newIndex = 0;
          break;
        case 'End':
          newIndex = TABS.length - 1;
          break;
        default:
          return;
      }

      e.preventDefault();
      const newTab = TABS[newIndex];
      setActiveTab(newTab);
      const newButton = document.getElementById(`cedros-tab-${newTab}`);
      newButton?.focus();
    },
    [activeTab]
  );

  const showEmail = isFeatureEnabled('email');
  const showGoogle = isFeatureEnabled('google') && config.googleClientId;
  const showApple = isFeatureEnabled('apple') && config.appleClientId && isApple;
  const showSolana = Boolean(renderSolanaButton) && isFeatureEnabled('solana') && hasWallets;
  const showPasskey = isFeatureEnabled('webauthn');
  const showDivider = showEmail && (showGoogle || showApple || showSolana || showPasskey);

  if (viewState === 'forgotPassword') {
    return (
      <div className={`cedros-login-form ${className}`}>
        <ForgotPasswordForm mode={forgotPasswordMode} onCancel={() => setViewState('form')} />
      </div>
    );
  }

  return (
    <div className={`cedros-login-form ${className}`}>
      {signupAccessCodeRequired && (
        <div className="cedros-form-field">
          <label htmlFor="login-form-access-code" className="cedros-label">
            Access Code
          </label>
          <input
            id="login-form-access-code"
            type="text"
            className="cedros-input"
            value={accessCode}
            onChange={(e) => setAccessCode(e.target.value)}
            placeholder="Enter access code"
            aria-required="true"
            autoComplete="off"
          />
        </div>
      )}

      {socialError && (
        <ErrorMessage
          error={socialError}
          onDismiss={() => setSocialError(null)}
        />
      )}

      {(showPasskey || showGoogle || showApple || showSolana) && (() => {
        const buttonMap: Record<string, ReactNode> = {
          webauthn: showPasskey ? <PasskeyLoginButton onSuccess={onSuccess} onError={handleSocialError} accessCode={accessCode || undefined} /> : null,
          google: showGoogle ? <GoogleLoginButton onSuccess={onSuccess} onError={handleSocialError} accessCode={accessCode || undefined} /> : null,
          apple: showApple ? <AppleLoginButton onSuccess={onSuccess} onError={handleSocialError} accessCode={accessCode || undefined} /> : null,
          solana: showSolana
            ? renderSolanaButton?.({
                onSuccess,
                onError: handleSocialError,
                accessCode: accessCode || undefined,
              })
            : null,
        };
        const order = socialButtonOrder ?? ['webauthn', 'google', 'apple', 'solana'];

        return (
          <div className="cedros-social-buttons">
            {order.map((id) => {
              const btn = buttonMap[id];
              return btn ? <Fragment key={id}>{btn}</Fragment> : null;
            })}
          </div>
        );
      })()}

      {showDivider && (
        <div className="cedros-divider">
          <span>Or continue with</span>
        </div>
      )}

      {showEmail && (
        <>
          <div className="cedros-tabs" role="tablist" aria-label="Authentication method">
            <button
              type="button"
              role="tab"
              id="cedros-tab-login"
              className={`cedros-tab ${activeTab === 'login' ? 'cedros-tab-active' : ''}`}
              onClick={() => setActiveTab('login')}
              onKeyDown={handleTabKeyDown}
              aria-selected={activeTab === 'login'}
              aria-controls="cedros-tabpanel-login"
              tabIndex={activeTab === 'login' ? 0 : -1}
            >
              Sign in
            </button>
            <button
              type="button"
              role="tab"
              id="cedros-tab-register"
              className={`cedros-tab ${activeTab === 'register' ? 'cedros-tab-active' : ''}`}
              onClick={() => setActiveTab('register')}
              onKeyDown={handleTabKeyDown}
              aria-selected={activeTab === 'register'}
              aria-controls="cedros-tabpanel-register"
              tabIndex={activeTab === 'register' ? 0 : -1}
            >
              Sign up
            </button>
          </div>

          <div
            role="tabpanel"
            id={`cedros-tabpanel-${activeTab}`}
            aria-labelledby={`cedros-tab-${activeTab}`}
          >
            {activeTab === 'login' ? (
              <EmailLoginForm
                onSuccess={onSuccess}
                onSwitchToRegister={() => setActiveTab('register')}
                onForgotPassword={() => setViewState('forgotPassword')}
              />
            ) : (
              <EmailRegisterForm
                onSuccess={onSuccess}
                onSwitchToLogin={() => setActiveTab('login')}
                accessCode={signupAccessCodeRequired ? accessCode : undefined}
              />
            )}
          </div>
        </>
      )}
    </div>
  );
}
